1	import { type ICtx, Scene, type SceneFrame } from "@threenative/core";
2	import { CollisionShape3D, type IPhysicsContext, RigidBody3D } from "@threenative/physics";
3	import { type Mesh, type PerspectiveCamera, Vector3 } from "three";
4	import { applyDirectDamage, applyRadiusDamage } from "../combat/damage.js";
5	import { Pickup } from "../entities/Pickup.js";
6	import {
7	  FRIENDLY_LAYER,
8	  HOSTILE_LAYER,
9	  PLAYER_LAYER,
10	  Player,
11	  SPAWN,
12	  WORLD_LAYER,
13	} from "../entities/Player.js";
14	import { Target } from "../entities/Target.js";
15	import { SpawnPoints } from "../level/SpawnPoints.js";
16	import { emitPlaytestEvent } from "../playtest-events.js";
17	import { createArenaCamera } from "../render/camera.js";
18	import { setupLighting } from "../render/lighting.js";
19	import { createLoadingScreen } from "../render/loading.js";
20	import { createMaterials } from "../render/materials.js";
21	import { setupPost } from "../render/postprocessing.js";
22	import { createArena, createFriendlyVisual, createWallVisual } from "../render/shapes.js";
23	import { setupSky } from "../render/sky.js";
24	import type { GameState } from "../state.js";
25	import { WaveDirector } from "../waves.js";
26	import { Hitscan } from "../weapons/Hitscan.js";
27	import { Projectile } from "../weapons/Projectile.js";
28	
29	export type GameCtx = ICtx<GameState, IPhysicsContext>;
30	
31	const AIM = new Vector3(0, 0, -1);
32	const DEMO_POSITION = new Vector3(0, 0.85, -4);
33	const WAVE_POSITION = new Vector3(0, 0.9, -9);
34	const SCAN_POSITION = new Vector3(3, 0.9, 0);
35	const BLAST_CENTRE = new Vector3(0, 0.85, -4);
36	const SPAWN_POINTS = new SpawnPoints([
37	  new Vector3(-0.4, SPAWN.y, SPAWN.z),
38	  SPAWN,
39	  new Vector3(0.4, SPAWN.y, SPAWN.z),
40	]);
41	
42	type TargetEntry = { readonly id: string; readonly target: Target };
43	
44	export class Play extends Scene<GameState, IPhysicsContext> {
45	  static override readonly initialState: GameState = {
46	    armor: 0,
47	    deaths: 0,
48	    demoTargetAlive: 1,
49	    friendlyPassed: 0,
50	    gameOver: 0,
51	    gameWon: 0,
52	    health: 100,
53	    hitDistanceTenths: 0,
54	    hitNormalXPercent: -101,
55	    hitNormalYPercent: -101,
56	    hitNormalZPercent: -101,
57	    lives: 3,
58	    pickups: 0,
59	    radiusInsideDeaths: 0,
60	    radiusMidAlive: 1,
61	    radiusNearAlive: 1,
62	    radiusOutsideAlive: -1,
63	    respawns: 0,
64	    scanCount: 0,
65	    score: 0,
66	    targetsRemaining: 1,
67	    wave: 1,
68	    wavesCleared: 0,
69	    wallBlocked: 0,
70	    phase: "playing",
71	  };
72	
73	  override enter(ctx: GameCtx): SceneFrame<GameState, IPhysicsContext> {
74	    const camera = ctx.camera as PerspectiveCamera;
75	    const materials = createMaterials();
76	    setupSky(ctx.scene);
77	    setupLighting(ctx.scene, ctx.renderer.raw as Parameters<typeof setupLighting>[1]);
78	    setupPost(ctx.renderer, ctx.scene, camera);
79	    const loading = createLoadingScreen(ctx);
80	    ctx.add(camera);
81	    const rig = createArenaCamera(camera);
82	    ctx.viewport.resize();
83	
84	    const arena = createArena(materials);
85	    ctx.add(arena.group);
86	    const arenaBody = (object: Mesh, shape: CollisionShape3D): RigidBody3D =>
87	      new RigidBody3D({
88	        collisionLayer: WORLD_LAYER,
89	        collisionMask: PLAYER_LAYER | HOSTILE_LAYER | FRIENDLY_LAYER,
90	        object,
91	        physics: ctx.physics,
92	        shape,
93	        type: "fixed",
94	      });
95	    arenaBody(arena.floor, CollisionShape3D.box(22, 0.4, 20));
96	    for (const wall of arena.walls) arenaBody(wall, CollisionShape3D.fromMesh(wall));
97	
98	    const playerRef: { value?: Player } = {};
99	    const getPlayer = (): Player => {
100	      if (playerRef.value === undefined) throw new Error("Shooter player is not initialized.");
101	      return playerRef.value;
102	    };
103	    const targets = new Map<number, Target>();
104	    const waveTargets: TargetEntry[] = [];
105	    const projectiles: Array<{ readonly id: string; readonly value: Projectile }> = [];
106	    let projectileIndex = 0;
107	    const waveDirector = new WaveDirector();
108	    const hitscan = new Hitscan();
109	    const spawnPoints = SPAWN_POINTS;
110	    const elapsed = { value: 0 };
111	
112	    const createEnemyProjectile = (origin: Vector3): void => {
113	      const direction = getPlayer().mesh.position.clone().sub(origin).normalize();
114	      const id = `projectile.enemy.${projectileIndex++}`;
115	      const projectile = new Projectile(
116	        ctx,
117	        materials,
118	        origin,
119	        direction,
120	        WORLD_LAYER | PLAYER_LAYER,
121	        (hit) => {
122	          if (hit.body.id === getPlayer().body.body.id) {
123	            getPlayer().takeDamage(20);
124	            emitPlaytestEvent({ entity: "player", name: "projectile-hit" });
125	          }
126	        },
127	      );
128	      projectiles.push({ id, value: projectile });
129	      ctx.entities.add(id, projectile);
130	    };
131	
132	    const registerTarget = (
133	      id: string,
134	      position: Vector3,
135	      options: ConstructorParameters<typeof Target>[3] = {},
136	      scan = true,
137	    ): Target => {
138	      const target = new Target(ctx, materials, position, {
139	        ...options,
140	        onFire: options.onFire ?? createEnemyProjectile,
141	      });
142	      targets.set(target.body.body.id, target);
143	      ctx.entities.add(id, target);
144	      if (scan) target.startScanning(ctx, getPlayer().body.body.id);
145	      return target;
146	    };
147	
148	    const removeEntity = (id: string): void => {
149	      if (ctx.entities.get(id) !== undefined) ctx.entities.remove(id);
150	    };
151	
152	    const onDamage = (amount: number): void => {
153	      const previous = ctx.state.getState();
154	      ctx.state.set({ health: getPlayer().health, score: previous.score, armor: 0 });
