import { HOSTILE_LAYER, PLAYER_LAYER, WORLD_LAYER } from "./Player.js";

type GameCtx = ICtx<GameState, IPhysicsContext>;

const PATROL_SPEED = 2.5;
const CHASE_SPEED = 4;
const FIRE_RANGE = 20;
const SIGHT_RANGE = 12;
const SIGHT_CONE = Math.cos(Math.PI / 6); // 60 degree cone

export class Enemy {
  readonly mesh: Group;
  readonly body: CharacterBody3D;
  readonly tags = ["hostile", "enemy"];
  health = 50;
  alive = true;
  #onFire: (origin: Vector3) => void;
  #fireTimer = 0;
  #agent: NavigationAgent3D;
  #navigation: NavigationRegion3D;
  #patrolWaypoints: Vector3[] = [];
  #currentWaypoint = 0;
  #chasing = false;
  #lastSightCheck = 0;
  #rightHandBone: Bone;

  constructor(
    ctx: GameCtx,
    materials: Parameters<typeof createEnemyVisual>[0],
    position: Vector3,
    navigation: NavigationRegion3D,
    options: {
      readonly onFire?: (origin: Vector3) => void;
      readonly patrolWaypoints?: Vector3[];
    } = {},
  ) {
    this.#navigation = navigation;
    this.#onFire = options.onFire ?? (() => undefined);
    this.#patrolWaypoints = options.patrolWaypoints ?? [
      position.clone(),
      position.clone().add(new Vector3(5, 0, 0)),
      position.clone().add(new Vector3(-5, 0, 0)),
    ];

    this.mesh = createEnemyVisual(materials);
    this.mesh.position.copy(position);
    ctx.add(this.mesh);

    // Create a RightHand bone for weapon attachment if it doesn't exist
    this.#rightHandBone = new Bone();
    this.#rightHandBone.name = "RightHand";
    this.#rightHandBone.position.set(0.4, 0.3, -0.3);
    this.mesh.add(this.#rightHandBone);

    // Create and attach rifle
    const rifle = this.createRifle(materials);
    attachToBone(this.mesh, "RightHand", rifle);

    this.body = new CharacterBody3D({
      collisionLayer: HOSTILE_LAYER,
      collisionMask: WORLD_LAYER | PLAYER_LAYER,
      autostep: { maxHeight: 0.25, minWidth: 0.18 },
      object: this.mesh,
      physics: ctx.physics,
      shape: CollisionShape3D.capsule(0.4, 0.35),
    });

    this.#agent = new NavigationAgent3D({
      navigation,
      object: this.mesh,
    });
  }

  private createRifle(materials: Parameters<typeof createEnemyVisual>[0]): Mesh {
    const rifleGroup = new Mesh(
      new CylinderGeometry(0.06, 0.08, 0.45, 6),
      materials.hostile,
    );
    rifleGroup.position.set(0, 0, -0.25);
    rifleGroup.rotation.z = Math.PI / 2;
    rifleGroup.castShadow = true;
    return rifleGroup;
  }

  update(ctx: GameCtx, playerPosition: Vector3, playerBodyId: number, dt: number): void {
    if (!this.alive) return;

    // Check if player is in sight
    this.#lastSightCheck -= dt;
    if (this.#lastSightCheck <= 0) {
      this.#lastSightCheck = 0.3;
      this.#chasing = this.canSeePlayer(ctx, playerPosition, playerBodyId);
    }

    const targetSpeed = this.#chasing ? CHASE_SPEED : PATROL_SPEED;
    const targetPos = this.#chasing ? playerPosition : this.#patrolWaypoints[this.#currentWaypoint];

    if (!this.#chasing) {
      const distToWaypoint = this.mesh.position.distanceTo(targetPos);
      if (distToWaypoint < 1) {
        this.#currentWaypoint = (this.#currentWaypoint + 1) % this.#patrolWaypoints.length;
      }
    }

    // Use navigation to move toward target
    this.#agent.setTargetPosition(targetPos);
    const nextPos = this.#agent.getNextPathPosition();

    if (nextPos) {
      const direction = nextPos.clone().sub(this.mesh.position).normalize();
      this.body.velocity.x = direction.x * targetSpeed;
      this.body.velocity.z = direction.z * targetSpeed;
    }

    this.body.moveAndSlide(dt);

    // Fire at player if close enough and chasing
    if (this.#chasing && this.mesh.position.distanceTo(playerPosition) < FIRE_RANGE) {
      this.#fireTimer -= dt;
      if (this.#fireTimer <= 0) {
        this.#fireTimer = 0.5;
        const fireOrigin = this.mesh.position.clone().add(new Vector3(0, 0.7, 0));
        this.#onFire(fireOrigin);
      }
    }
  }

  private canSeePlayer(ctx: GameCtx, playerPosition: Vector3, playerBodyId: number): boolean {
    const distToPlayer = this.mesh.position.distanceTo(playerPosition);
    if (distToPlayer > SIGHT_RANGE) return false;

    // Check field of view (cone check)
    const dirToPlayer = playerPosition.clone().sub(this.mesh.position).normalize();
    const enemyForward = new Vector3(0, 0, -1).applyQuaternion(this.mesh.quaternion);
    const dotProduct = dirToPlayer.dot(enemyForward);
    if (dotProduct < SIGHT_CONE) return false;

    // Raycast to ensure line of sight
    const hit = directSpaceState(ctx.physics).intersectRay({
      collisionMask: PLAYER_LAYER,
      from: this.mesh.position.clone().add(new Vector3(0, 0.6, 0)),
      to: playerPosition,
    });

    return hit?.body.id === playerBodyId;
  }

  takeDamage(amount: number): boolean {
    if (!this.alive || !Number.isFinite(amount) || amount <= 0) return false;
    this.health = Math.max(0, this.health - amount);
    if (this.health > 0) return false;
    this.alive = false;
    this.mesh.visible = false;
    return true;
  }

  debug(): Record<string, unknown> {
    return {
      alive: this.alive,
      chasing: this.#chasing,
      health: this.health,
      position: this.mesh.position.toArray(),
    };
  }

  dispose(): void {
    this.#agent.dispose?.();
    this.body.dispose();
    this.mesh.removeFromParent();
  }
}

